import type { AssetManifest, AudioManifest } from '@content/schema';

/**
 * The slim manifests the app ships (D23). The full manifests (transcripts, licences, review notes)
 * are for tooling and reviewers; the app only needs which clip files exist and whether they are
 * approved, and each asset's file and size. Generated by `pnpm content:runtime`; `content:validate`
 * fails if the committed files are stale.
 */
export type ClipStatus = 'placeholder' | 'draft' | 'approved' | (string & {});
export interface RuntimeAudio {
  schemaVersion: 1;
  /** Clip id → status per available language slot. Files are `assets/audio/<slot>/<id>.mp3`. */
  clips: Record<string, Partial<Record<'ar' | 'en' | 'common', ClipStatus>>>;
}

export type RuntimeAssets = Record<string, { url: string; w: number; h: number; placeholder: boolean }>;

export const clipPath = (id: string, slot: 'ar' | 'en' | 'common') => `assets/audio/${slot}/${id}.mp3`;

export function runtimeAudio(m: AudioManifest): RuntimeAudio {
  const clips: RuntimeAudio['clips'] = {};
  for (const c of m.clips) {
    const slots: RuntimeAudio['clips'][string] = {};
    for (const slot of ['ar', 'en', 'common'] as const) {
      const status = c.review[slot]?.status;
      if (c.files[slot] && status && status !== 'planned') slots[slot] = status;
    }
    if (Object.keys(slots).length) clips[c.id] = slots;
  }
  return { schemaVersion: 1, clips };
}

export function runtimeAssets(m: AssetManifest): RuntimeAssets {
  const out: RuntimeAssets = {};
  for (const a of m.assets) {
    const file = a.files[0];
    if (!file || a.status === 'planned') continue;
    out[a.id] = { url: `/${file}`, w: a.displaySize1x?.w ?? 200, h: a.displaySize1x?.h ?? 200, placeholder: a.status !== 'approved' };
  }
  return out;
}

/** Manifest entries whose files do not follow the fixed path the runtime manifest relies on. */
export function nonStandardClipPaths(m: AudioManifest): string[] {
  return m.clips.flatMap((c) =>
    (['ar', 'en', 'common'] as const).filter((s) => c.files[s] && c.files[s] !== clipPath(c.id, s)).map((s) => `${c.id} (${s}): ${c.files[s]}`),
  );
}
